INSERT INTO `loai_tin_dichvuu` (`id`, `thuocloai`, `thuocloai_en`, `trangchu`, `hinhanh`, `logo`, `noidung`, `noidung_en`, `name_url`, `tukhoa1`, `tukhoa2`) VALUES
