yle=\"line-height: 16.56px; font-family: Arial, sans-serif;\">&nbsp;<span lang=\"VI\">với trang thiết bị linh kiện ch&iacute;nh h&atilde;ng bảo h&agrave;nh theo đ&uacute;ng ti&ecirc;u chuẩn. L&agrave;m một lần bảo h&agrave;nh một năm,&nbsp;</span></span><span style=\"line-height: 16.56px; font-family: Arial, sans-serif;\">đảm bảo đ&aacute;p ứng tốt nhất mong muốn của kh&aacute;ch&nbsp;</span><span lang=\"VI\" style=\"line-height: 16.56px; font-family: Arial, sans-serif;\">h&agrave;ng.</span></span><span lang=\"VI\" style=\"font-size: 14pt; line-height: 21.4667px; font-family: Arial, sans-serif;\"><o:p></o:p></span></p>\r\n\r\n<p><span style=\"font-size: larger;\"><span lang=\"VI\" style=\"line-height: 16.56px; font-family: Arial, sans-serif;\">H&atilde;y li&ecirc;n hệ ngay cho ch&uacute;ng t&ocirc;i:&nbsp;<span style=\"color: red;\">0932 876 323</span></span></span></p>\r\n', '', 'Sửa chữa máy lạnh tại nhà của Điện Lạnh Tấn Tài luôn đảm bảo giá rẻ hơn thị trường, sự chuyên nghiệp của đội ngũ nhân viên nhiều năm kinh nghiệm.', 'Sửa điện lạnh Bến Cát- Bình Dương', 'Sửa điện lạnh Bến Cát- Bình Dương', '', '', '', 'Sửa máy lạnh tại nhà Bến Cát', '', '', 'sua-dien-lanh-ben-cat--binh-duong', ' 06/08/2026 ', 1, '', '9266', '9266', '9266Suachuadienlanh_bencatsw.jpg', '9266', '9266', 14, 0);
INSERT INTO `tin_dichvu` (`id`, `hinhanh`, `noidung`, `trangchu`, `mota`, `tieude`, `tieude_en`, `noidung_en`, `mota_en`, `title`, `tukhoa`, `tukhoa2`, `facebook`, `linkurl`, `ngay`, `xem`, `nguon`, `hinhqcab`, `hinhqcabc`, `hinhndab`, `hinhndabc`, `hinhndabcd`, `thuocloai`, `noibat`) VALUES
(128, '5092bomgamaylanhdautieng.jpg', '<p class=\"MsoNormal\"><b style=\"mso-bidi-font-weight:normal\"><span lang=\"VI\" style=\"font-size:14.0pt;line-height:107%;font-family:&quot;Arial&quot;,sans-serif;\r\nmso-fareast-font-family:&quot;Times New Roman&quot;;color:red;mso-ansi-language:VI\"><span style=\"mso-spacerun:yes\">&nbsp;&nbsp; </span>Bơm ga điều h&ograve;a tại nh&agrave;<span style=\"mso-spacerun:yes\">&nbsp;&nbsp; </span><o:p></o:p></span></b></p>\r\n\r\n<p class=\"MsoNormal\"><span lang=\"VI\" style=\"font-size:14.0pt;line-height:107%;\r\nfont-family:&quot;Arial&quot;,sans-serif;mso-fareast-font-family:&quot;Times New Roman&quot;;\r\nmso-ansi-language:VI\"><span style=\"mso-spacerun:yes\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span>Nếu như điều h&ograve;a </span><span style=\"font-size:14.0pt;line-height:107%;font-family:&quot;Arial&quot;,sans-serif;\r\nmso-fareast-font-family:&quot;Times New Roman&quot;\">nh&agrave; bạn hết </span><span lang=\"VI\" style=\"font-size:14.0pt;line-height:107%;font-family:&quot;Arial&quot;,sans-serif;\r\nmso-fareast-font-family:&quot;Times New Roman&quot;;mso-ansi-language:VI\">gas</span><span style=\"font-size:14.0pt;line-height:107%;font-family:&quot;Arial&quot;,sans-serif;\r\nmso-fareast-font-family:&quot;Times New Roman&quot;\"> m&agrave; bạn kh&ocirc;ng biết vẫn tiếp tục cho m&aacute;y l&agrave;m việc th&igrave; sẽ l&agrave;m </span><span lang=\"VI\" style=\"font-size:14.0pt;\r\nline-height:107%;font-family:&quot;Arial&quot;,sans-serif;mso-fareast-font-family:&quot;Times New Roman&quot;;\r\nmso-ansi-language:VI\">điều h&ograve;a </span><span style=\"font-size:14.0pt;line-height:\r\n107%;font-family:&quot;Arial&quot;,sans-serif;mso-fareast-font-family:&quot;Times New Roman&quot;\">c&agrave;ng hư hỏng nhiều hơn, bạn sẽ phải mất nhiều tiền để sửa ch&uacute;ng. </span><span lang=\"VI\" style=\"font-size:14.0pt;line-height:107%;font-family:&quot;Arial&quot;,sans-serif;\r\nmso-fareast-font-family:&quot;Times New Roman&quot;;mso-ansi-language:VI\">K</span><span style=\"font-size:14.0pt;line-height:107%;font-family:&quot;Arial&quot;,sans-serif;\r\nmso-fareast-font-family:&quot;Times New Roman&quot;\">hi </span><span lang=\"VI\" style=\"font-size:14.0pt;line-height:107%;font-family:&quot;Arial&quot;,sans-serif;\r\nmso-fareast-font-family:&quot;Times New Roman&quot;;mso-ansi-language:VI\">điều h&ograve;a </span><span style=\"font-size:14.0pt;line-height:107%;font-family:&quot;Arial&quot;,sans-serif;\r\nmso-fareast-font-family:&quot;Times New Roman&quot;\">nh&agrave; bạn gặp một trong những sự cố hết gas hay thiếu gas, kh&aacute;ch h&agrave;ng thường gặp kh&oacute; khăn trong việc t&igrave;m kiếm v&agrave; lựa chọn trung t&acirc;m cung cấp dịch vụ bơm gas </span><span lang=\"VI\" style=\"font-size:14.0pt;line-height:107%;font-family:&quot;Arial&quot;,sans-serif;\r\nmso-fareast-font-family:&quot;Times New Roman&quot;;mso-ansi-language:VI\">điều h&ograve;a </span><span style=\"font-size:14.0pt;line-height:107%;font-family:&quot;Arial&quot;,sans-serif;\r\nmso-fareast-font-family:&quot;Times New Roman&quot;\">uy t&iacute;n, chất lượng, đảm bảo v&agrave; gi&aacute; cả hợp </span><span lang=\"VI\" style=\"font-size:14.0pt;line-height:107%;\r\nfont-family:&quot;Arial&quot;,sans-serif;mso-fareast-font-family:&quot;Times New Roman&quot;;\r\nmso-ansi-language:VI\">l&yacute;</span><span lang=\"VI\" style=\"font-size:14.0pt;\r\nline-height:107%;font-family:&quot;Arial&quot;,sans-serif;mso-ansi-language:VI\">.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\"><span lang=\"VI\" style=\"font-size:14.0pt;line-height:107%;\r\nfont-family:&quot;Arial&quot;,sans-serif;mso-ansi-language:VI\"><span style=\"mso-spacerun:yes\">&nbsp;&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size:14.0pt;\r\nline-height:107%;font-family:&quot;Arial&quot;,sans-serif;color:#222222;background:white\">&nbsp;</span><span lang=\"VI\" style=\"font-size:14.0pt;line-height:107%;font-family:&quot;Arial&quot;,sans-serif;\r\ncolor:#222222;background:white;mso-ansi-language:VI\">Đừng suy nghĩ nhiều m&agrave; h&atilde;y gọi ngay cho ch&uacute;ng t&ocirc;i </span><span lang=\"VI\" style=\"font-size:14.0pt;line-height:\r\n107%;font-family:&quot;Arial&quot;,sans-serif;color:#4472C4;mso-themecolor:accent5;\r\nbackground:white;mso-ansi-language:VI\">Điện lạnh Tấn T&agrave;i</span><span lang=\"VI\" style=\"font-size:14.0pt;line-height:107%;font-family:&quot;Arial&quot;,sans-serif;\r\ncolor:#222222;background:white;mso-ansi-language:VI\">, với nhiều năm kinh nghiệm tr&ecirc;n lĩnh vực điện lạnh c&ugrave;ng đội ngũ nh&acirc;n vi&ecirc;n c&oacute; tay nghề cao, th&acirc;n thiện v&agrave; hệ thống chi nh&aacute;nh trải rộng khắp tỉnh B&igrave;nh Dương, cam kết cung cấp cho qu&yacute; kh&aacute;ch h&agrave;ng dịch vụ bơm ga với gi&aacute; cả ph&ugrave; hợp, uy t&iacute;n chất lượng cao.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\"><span lang=\"VI\" style=\"font-size:14.0pt;line-height:107%;\r\nfont-family:&quot;Arial&quot;,sans-serif;color:#222222;background:white;mso-ansi-language:\r\nVI\"><span style=\"mso-spacerun:yes\">&nbsp;&nbsp; </span>Hotline: </span><span lang=\"VI\" style=\"font-size:14.0pt;line-height:107%;font-family:&quot;Arial&quot;,sans-serif;\r\ncolor:red;background:white;mso-ansi-language:VI\">0932 876 323</span><br />\r\n&nbsp;</p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align: center;\"><span lang=\"VI\" style=\"font-size:14.0pt;line-height:107%;font-family:&quot;Arial&quot;,sans-serif;\r\ncolor:red;background:white;mso-ansi-language:VI\"><img alt=\"Bơm ga điều hòa Bình Dương\" height=\"500\" src=\"/demo1/tinhchi/hinhanh_fckeditor/bomgamaylanhtainha.jpg\" width=\"750\" /></span><span lang=\"VI\" style=\"font-size:14.0pt;line-height:107%;font-family:&quot;Arial&quot;,sans-serif;\r\ncolor:#222222;background:white;mso-ansi-language:VI\"><o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"margin-bottom:15.0pt;line-height:normal;background:\r\nwhite;vertical-align:baseline\"><b style=\"mso-bidi-font-weight:normal\"><span style=\"font-size:14.0pt;font-family:&quot;Arial&quot;,sans-serif;mso-fareast-font-family:\r\n&quot;Times New Roman&quot;;color:red\">T&aacute;c dụng nạp gas điều h&ograve;a định k&igrave;<o:p></o:p></span></b></p>\r\n\r\n<p class=\"MsoListParagraphCxSpFirst\" style=\"margin-bottom:15.0pt;mso-add-space:\r\nauto;text-indent:-18.0pt;line-height:normal;mso-list:l3 level1 lfo1;background:\r\nwhite;vertical-align:baseline\"><!--[if !supportLists]--><span style=\"font-size:\r\n14.0pt;font-family:Wingdings;mso-fareast-font-family:Wingdings;mso-bidi-font-family:\r\nWingdings\"><span style=\"mso-list:Ignore\">&uuml;<span style=\"font:7.0pt &quot;Times New Roman&quot;\"> </span></span></span><!--[endif]--><span style=\"font-size:14.0pt;font-family:&quot;Arial&quot;,sans-serif;\r\nmso-fareast-font-family:&quot;Times New Roman&quot;\">Tăng hiệu quả sử dụng<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoListParagraphCxSpMiddle\" style=\"margin-bottom:15.0pt;mso-add-space:\r\nauto;text-indent:-18.0pt;line-height:normal;mso-list:l3 level1 lfo1;background:\r\nwhite;vertical-align:baseline\"><!--[if !supportLists]--><span style=\"font-size:\r\n14.0pt;font-family:Wingdings;mso-fareast-font-family:Wingdings;mso-bidi-font-family:\r\nWingdings\"><span style=\"mso-list:Ignore\">&uuml;<span style=\"font:7.0pt &quot;Times New Roman&quot;\"> </span></span></span><!--[endif]--><span style=\"font-size:14.0pt;font-family:&quot;Arial&quot;,sans-serif;\r\nmso-fareast-font-family:&quot;Times New Roman&quot;\">Giảm thiểu tiền điện hằng th&aacute;ng<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoListParagraphCxSpMiddle\" style=\"margin-bottom:15.0pt;mso-add-space:\r\nauto;text-indent:-18.0pt;line-height:normal;mso-list:l3 level1 lfo1;background:\r\nwhite;vertical-align:baseline\"><!--[if !supportLists]--><span style=\"font-size:\r\n14.0pt;font-family:Wingdings;mso-fareast-font-family:Wingdings;mso-bidi-font-family:\r\nWingdings\"><span style=\"mso-list:Ignore\">&uuml;<span style=\"font:7.0pt &quot;Times New Roman&quot;\"> </span></span></span><!--[endif]--><span style=\"font-size:14.0pt;font-family:&quot;Arial&quot;,sans-serif;\r\nmso-fareast-font-family:&quot;Times New Roman&quot;\">Tăng tuổi thọ cho m&aacute;y điều h&ograve;a<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoListParagraphCxSpLast\" style=\"margin-bottom:15.0pt;mso-add-space:\r\nauto;text-indent:-18.0pt;line-height:normal;mso-list:l3 level1 lfo1;background:\r\nwhite;vertical-align:baseline\"><!--[if !supportLists]--><span style=\"font-size:\r\n14.0pt;font-family:Wingdings;mso-fareast-font-family:Wingdings;mso-bidi-font-family:\r\nWingdings\"><span style=\"mso-list:Ignore\">&uuml;<span style=\"font:7.0pt &quot;Times New Roman&quot;\"> </span></span></span><!--[endif]--><span style=\"font-size:14.0pt;font-family:&quot;Arial&quot;,sans-serif;\r\nmso-fareast-font-family:&quot;Times New Roman&quot;\">Gi&uacute;p m&aacute;y điều h&ograve;a l&agrave;m lạnh nhanh<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\"><b style=\"mso-bidi-font-weight:normal\"><span lang=\"VI\" style=\"font-size:14.0pt;line-height:107%;font-family:&quot;Arial&quot;,sans-serif;\r\ncolor:red;mso-ansi-language:VI\"><span style=\"mso-spacerun:yes\">&nbsp; </span>Điều h&ograve;a cần nạp gas khi thiết bị của bạn c&oacute; một số dấu hiệu sau đ&acirc;y<o:p></o:p></span></b></p>\r\n\r\n<p class=\"MsoListParagraph\" style=\"text-indent:-18.0pt;mso-list:l4 level1 lfo5\"><!--[if !supportLists]--><b style=\"mso-bidi-font-weight:normal\"><span style=\"font-size:14.0pt;line-height:\r\n107%;font-family:&quot;Arial&quot;,sans-serif;mso-fareast-font-family:Arial\"><span style=\"mso-list:Ignore\">1.<span style=\"font:7.0pt &quot;Times New Roman&quot;\">&nbsp;&nbsp;&nbsp; </span></span></span></b><!--[endif]--><b style=\"mso-bidi-font-weight:normal\"><span style=\"font-size:14.0pt;line-height:107%;font-family:&quot;Arial&quot;,sans-serif\">M&aacute;y lạnh tự tắt mở<o:p></o:p></span></b></p>\r\n\r\n<p class=\"MsoNormal\"><span lang=\"VI\" style=\"font-size:14.0pt;line-height:107%;\r\nfont-family:&quot;Arial&quot;,sans-serif;mso-ansi-language:VI\"><span style=\"mso-spacerun:yes\">&nbsp;&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size:14.0pt;\r\nline-height:107%;font-family:&quot;Arial&quot;,sans-serif\">M&aacute;y lạnh hoạt động được 15 ph&uacute;t th&igrave; tự động bật tắt li&ecirc;n tục l&agrave; dấu hiệu cho thấy m&aacute;y lạnh đang bị thiếu gas. Nếu sau khi kiểm tra c&aacute;c chế độ tr&ecirc;n remote m&agrave; kh&ocirc;ng c&oacute; g&igrave; bất thường th&igrave; khả năng m&aacute;y lạnh nh&agrave; bạn đang bị thiếu gas rất lớn.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoListParagraph\" style=\"text-indent:-18.0pt;line-height:106%;\r\nmso-list:l4 level1 lfo5\"><!--[if !supportLists]--><b style=\"mso-bidi-font-weight:\r\nnormal\"><span style=\"font-size:14.0pt;line-height:106%;font-family:&quot;Arial&quot;,sans-serif;\r\nmso-fareast-font-family:Arial\"><span style=\"mso-list:Ignore\">2.<span style=\"font:7.0pt &quot;Times New Roman&quot;\">&nbsp;&nbsp;&nbsp; </span></span></span></b><!--[endif]--><b style=\"mso-bidi-font-weight:normal\"><span style=\"font-size:14.0pt;line-height:\r\n106%;font-family:&quot;Arial&quot;,sans-serif\">Chảy nước tr&ecirc;n d&agrave;n lạnh<o:p></o:p></span></b></p>\r\n\r\n<p class=\"MsoNormal\"><span lang=\"VI\" style=\"font-size:14.0pt;line-height:107%;\r\nfont-family:&quot;Arial&quot;,sans-serif;mso-ansi-language:VI\"><span style=\"mso-spacerun:yes\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size:14.0pt;\r\nline-height:107%;font-family:&quot;Arial&quot;,sans-serif\">Đ&acirc;y ch&iacute;nh l&agrave; một trong những biểu hiện sẽ thấy khi m&aacute;y lạnh nh&agrave; bạn cần &ldquo; nạp gas</span><span style=\"font-size:14.0pt;line-height:107%;font-family:&quot;Arial&quot;,sans-serif;\r\nmso-ansi-language:VI\"> </span><span style=\"font-size:14.0pt;line-height:107%;\r\nfont-family:&quot;Arial&quot;,sans-serif\">&rdquo;, m&aacute;y lạnh sẽ c&oacute; dấu hiệu bị x&igrave;-&gt; m&aacute;y lạnh b&aacute;m nhiều tuyết-&gt; nặng hơn c&oacute; thể dẫn đến t&igrave;nh trạng đ&ocirc;ng đ&aacute; b&ecirc;n trong d&agrave;n lạnh. Nếu m&aacute;y lạnh nh&agrave; bạn c&oacute; xảy ra t&igrave;nh trạng thế n&agrave;y th&igrave; nhanh ch&oacute;ng kiểm tra v&agrave; nạp ngay kh&iacute; gas v&agrave;o nh&eacute;!<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoListParagraph\" style=\"text-indent:-18.0pt;line-height:106%;\r\nmso-list:l4 level1 lfo5\"><!--[if !supportLists]--><b style=\"mso-bidi-font-weight:\r\nnormal\"><span style=\"font-size:14.0pt;line-height:106%;font-family:&quot;Arial&quot;,sans-serif;\r\nmso-fareast-font-family:Arial\"><span style=\"mso-list:Ignore\">3.<span style=\"font:7.0pt &quot;Times New Roman&quot;\">&nbsp;&nbsp;&nbsp; </span></span></span></b><!--[endif]--><b style=\"mso-bidi-font-weight:normal\"><span lang=\"VI\" style=\"font-size:14.0pt;\r\nline-height:106%;font-family:&quot;Arial&quot;,sans-serif;mso-ansi-language:VI\">Điều h&ograve;a </span></b><b style=\"mso-bidi-font-weight:normal\"><span style=\"font-size:14.0pt;line-height:\r\n106%;font-family:&quot;Arial&quot;,sans-serif\">kh&ocirc;ng lạnh ( hoặc lạnh yếu</span></b><b style=\"mso-bidi-font-weight:normal\"><span style=\"font-size:14.0pt;line-height:\r\n106%;font-family:&quot;Arial&quot;,sans-serif;mso-ansi-language:VI\"> </span></b><b style=\"mso-bidi-font-weight:normal\"><span style=\"font-size:14.0pt;line-height:\r\n106%;font-family:&quot;Arial&quot;,sans-serif\">)<o:p></o:p></span></b></p>\r\n\r\n<p class=\"MsoNormal\"><span lang=\"VI\" style=\"font-size:14.0pt;line-height:107%;\r\nfont-family:&quot;Arial&quot;,sans-serif;mso-ansi-language:VI\"><span style=\"mso-spacerun:yes\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size:14.0pt;\r\nline-height:107%;font-family:&quot;Arial&quot;,sans-serif\">Khi đ&atilde; hoạt động </span><span lang=\"VI\" style=\"font-size:14.0pt;line-height:107%;font-family:&quot;Arial&quot;,sans-serif;\r\nmso-ansi-language:VI\">điều h&ograve;a </span><span style=\"font-size:14.0pt;line-height:\r\n107%;font-family:&quot;Arial&quot;,sans-serif\">trong một khoảng thời gian nhất định m&agrave; vẫn kh&ocirc;ng cảm nhận đủ hơi lạnh được ph&aacute;t ra nguy&ecirc;n nh&acirc;n rất cao &ldquo; </span><span lang=\"VI\" style=\"font-size:14.0pt;line-height:107%;font-family:&quot;Arial&quot;,sans-serif;\r\nmso-ansi-language:VI\">điều h&ograve;a</span><span style=\"font-size:14.0pt;line-height:\r\n107%;font-family:&quot;Arial&quot;,sans-serif\"> nh&agrave; bạn đ&atilde; thiếu gas, cần phải nạp ngay&rdquo; để đ&aacute;p ứng nhu cầu được tốt hơn nhiều.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\"><b style=\"mso-bidi-font-weight:normal\"><span lang=\"VI\" style=\"font-size:14.0pt;line-height:107%;font-family:&quot;Arial&quot;,sans-serif;\r\ncolor:red;mso-ansi-language:VI\">C&aacute;c bước bơm ga điều h&ograve;a<o:p></o:p></span></b></p>\r\n\r\n<p class=\"MsoListParagraph\" style=\"margin-bottom:9.0pt;mso-add-space:auto;\r\ntext-indent:-18.0pt;line-height:normal;mso-outline-level:3;mso-list:l0 level1 lfo2;\r\nbackground:white;vertical-align:baseline\"><!--[if !supportLists]--><span style=\"font-size:14.0pt;font-family:Wingdings;mso-fareast-font-family:Wingdings;\r\nmso-bidi-font-family:Wingdings\"><span style=\"mso-list:Ignore\">&Oslash;<span style=\"font:7.0pt &quot;Times New Roman&quot;\"> </span></span></span><!--[endif]--><b style=\"mso-bidi-font-weight:normal\"><u><span style=\"font-size:14.0pt;\r\nfont-family:&quot;Arial&quot;,sans-serif;mso-fareast-font-family:&quot;Times New Roman&quot;\">Bước 1</span></u></b><b style=\"mso-bidi-font-weight:normal\"><span style=\"font-size:\r\n14.0pt;font-family:&quot;Arial&quot;,sans-serif;mso-fareast-font-family:&quot;Times New Roman&quot;\">: </span></b><b style=\"mso-bidi-font-weight:normal\"><span lang=\"VI\" style=\"font-size:14.0pt;font-family:&quot;Arial&quot;,sans-serif;mso-fareast-font-family:\r\n&quot;Times New Roman&quot;;mso-ansi-language:VI\">Kiểm</span></b><b style=\"mso-bidi-font-weight:\r\nnormal\"><span style=\"font-size:14.0pt;font-family:&quot;Arial&quot;,sans-serif;\r\nmso-fareast-font-family:&quot;Times New Roman&quot;\"> tra lượng gas tr&ecirc;n </span></b><b style=\"mso-bidi-font-weight:normal\"><span lang=\"VI\" style=\"font-size:14.0pt;\r\nfont-family:&quot;Arial&quot;,sans-serif;mso-fareast-font-family:&quot;Times New Roman&quot;;\r\nmso-ansi-language:VI\">điều h&ograve;a</span></b><b style=\"mso-bidi-font-weight:normal\"><span style=\"font-size:14.0pt;font-family:&quot;Arial&quot;,sans-serif;mso-fareast-font-family:\r\n&quot;Times New Roman&quot;\"><o:p></o:p></span></b></p>\r\n\r\n<p class=\"MsoNormal\" style=\"margin-bottom:15.0pt;line-height:normal;background:\r\nwhite;vertical-align:baseline\"><span lang=\"VI\" style=\"font-size:14.0pt;\r\nfont-family:&quot;Arial&quot;,sans-serif;mso-fareast-font-family:&quot;Times New Roman&quot;;\r\nmso-ansi-language:VI\"><span style=\"mso-spacerun:yes\">&nbsp;&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size:14.0pt;font-family:&quot;Arial&quot;,sans-serif;mso-fareast-font-family:\r\n&quot;Times New Roman&quot;\">Bạn d&ugrave;ng tovit th&aacute;o to&agrave;n bộ vỏ <span style=\"mso-tab-count:\r\n1\"> </span>ra, sau đ&oacute; d&ugrave;ng mỏ lết vặn c&aacute;c đầu ốc nạp gas ra.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"margin-bottom:15.0pt;line-height:normal;background:\r\nwhite;vertical-align:baseline\"><span lang=\"VI\" style=\"font-size:14.0pt;\r\nfont-family:&quot;Arial&quot;,sans-serif;mso-fareast-font-family:&quot;Times New Roman&quot;;\r\nmso-ansi-language:VI\"><span style=\"mso-spacerun:yes\">&nbsp;&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size:14.0pt;font-family:&quot;Arial&quot;,sans-serif;mso-fareast-font-family:\r\n&quot;Times New Roman&quot;\">Nối một d&acirc;y đồng hồ v&agrave;o van nạp gas, d&acirc;y kia vặn v&agrave;o chai gas để xem &aacute;p xuất gas trong </span><span lang=\"VI\" style=\"font-size:14.0pt;\r\nfont-family:&quot;Arial&quot;,sans-serif;mso-fareast-font-family:&quot;Times New Roman&quot;;\r\nmso-ansi-language:VI\">điều h&ograve;a </span><span style=\"font-size:14.0pt;font-family:\r\n&quot;Arial&quot;,sans-serif;mso-fareast-font-family:&quot;Times New Roman&quot;\">l&uacute;c n&agrave;y l&agrave; bao nhi&ecirc;u.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"margin-bottom:15.0pt;line-height:normal;background:\r\nwhite;vertical-align:baseline\"><span lang=\"VI\" style=\"font-size:14.0pt;\r\nfont-family:&quot;Arial&quot;,sans-serif;mso-fareast-font-family:&quot;Times New Roman&quot;;\r\nmso-ansi-language:VI\"><span style=\"mso-spacerun:yes\">&nbsp;&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size:14.0pt;font-family:&quot;Arial&quot;,sans-serif;mso-fareast-font-family:\r\n&quot;Times New Roman&quot;\">Tiếp đ&oacute;, kiểm tra v&agrave; xử l&yacute; triệt để t&igrave;nh trạng r&ograve; rỉ của hệ thống đường ống dẫn lạnh.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoListParagraph\" style=\"margin-bottom:9.0pt;mso-add-space:auto;\r\ntext-indent:-18.0pt;line-height:normal;mso-outline-level:3;mso-list:l2 level1 lfo3;\r\nbackground:white;vertical-align:baseline\"><!--[if !supportLists]--><span style=\"font-size:14.0pt;font-family:Wingdings;mso-fareast-font-family:Wingdings;\r\nmso-bidi-font-family:Wingdings\"><span style=\"mso-list:Ignore\">&Oslash;<span style=\"font:7.0pt &quot;Times New Roman&quot;\"> </span></span></span><!--[endif]--><b style=\"mso-bidi-font-weight:normal\"><u><span style=\"font-size:14.0pt;\r\nfont-family:&quot;Arial&quot;,sans-serif;mso-fareast-font-family:&quot;Times New Roman&quot;\">Bước 2</span></u></b><b style=\"mso-bidi-font-weight:normal\"><span style=\"font-size:\r\n14.0pt;font-family:&quot;Arial&quot;,sans-serif;mso-fareast-font-family:&quot;Times New Roman&quot;\">: H&uacute;t ch&acirc;n kh&ocirc;ng<o:p></o:p></span></b></p>\r\n\r\n<p class=\"MsoNormal\" style=\"margin-bottom:15.0pt;line-height:normal;background:\r\nwhite;vertical-align:baseline\"><span lang=\"VI\" style=\"font-size:14.0pt;\r\nfont-family:&quot;Arial&quot;,sans-serif;mso-fareast-font-family:&quot;Times New Roman&quot;;\r\nmso-ansi-language:VI\"><span style=\"mso-spacerun:yes\">&nbsp;&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size:14.0pt;font-family:&quot;Arial&quot;,sans-serif;mso-fareast-font-family:\r\n&quot;Times New Roman&quot;\">Tr&aacute;nh t&igrave;nh trạng c&oacute; nhiều hỗn hợp kh&iacute; c&ugrave;ng gas đi v&agrave;o hệ thống kh&iacute; </span><span lang=\"VI\" style=\"font-size:14.0pt;font-family:&quot;Arial&quot;,sans-serif;\r\nmso-fareast-font-family:&quot;Times New Roman&quot;;mso-ansi-language:VI\">điều h&ograve;a.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"margin-bottom:15.0pt;line-height:normal;background:\r\nwhite;vertical-align:baseline\"><span lang=\"VI\" style=\"font-size:14.0pt;\r\nfont-family:&quot;Arial&quot;,sans-serif;mso-fareast-font-family:&quot;Times New Roman&quot;;\r\nmso-ansi-language:VI\"><span style=\"mso-spacerun:yes\">&nbsp;&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size:14.0pt;font-family:&quot;Arial&quot;,sans-serif;mso-fareast-font-family:\r\n&quot;Times New Roman&quot;\">V&igrave; thế, để c&oacute; c&aacute;ch nạp ga </span><span lang=\"VI\" style=\"font-size:14.0pt;font-family:&quot;Arial&quot;,sans-serif;mso-fareast-font-family:\r\n&quot;Times New Roman&quot;;mso-ansi-language:VI\">điều h&ograve;a </span><span style=\"font-size:\r\n14.0pt;font-family:&quot;Arial&quot;,sans-serif;mso-fareast-font-family:&quot;Times New Roman&quot;\">đ&uacute;ng kỹ thuật bạn cần phải d&ugrave;ng m&aacute;y h&uacute;t ch&acirc;n kh&ocirc;ng kh&iacute; chuy&ecirc;n dụng để h&uacute;t to&agrave;n bộ kh&ocirc;ng kh&iacute; c&oacute; trong đường hệ thống ống dẫn.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"margin-bottom:15.0pt;line-height:normal;background:\r\nwhite;vertical-align:baseline\"><span lang=\"VI\" style=\"font-size:14.0pt;\r\nfont-family:&quot;Arial&quot;,sans-serif;mso-fareast-font-family:&quot;Times New Roman&quot;;\r\nmso-ansi-language:VI\"><span style=\"mso-spacerun:yes\">&nbsp;&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size:14.0pt;font-family:&quot;Arial&quot;,sans-serif;mso-fareast-font-family:\r\n&quot;Times New Roman&quot;\">L&uacute;c n&agrave;y đồng hồ hạ &aacute;p về độ ẩm, bạn tiến h&agrave;nh kh&oacute;a van lại v&agrave; tắt m&aacute;t h&uacute;t để trong v&ograve;ng từ 30 ph&uacute;t đến 60 ph&uacute;t.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"margin-bottom:15.0pt;line-height:normal;background:\r\nwhite;vertical-align:baseline\"><span lang=\"VI\" style=\"font-size:14.0pt;\r\nfont-family:&quot;Arial&quot;,sans-serif;mso-fareast-font-family:&quot;Times New Roman&quot;;\r\nmso-ansi-language:VI\"><span style=\"mso-spacerun:yes\">&nbsp;&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size:14.0pt;font-family:&quot;Arial&quot;,sans-serif;mso-fareast-font-family:\r\n&quot;Times New Roman&quot;\">Cho đến khi kim đồng hồ chỉ đến vạch số 0 th&igrave; l&uacute;c n&agrave;y bạn đ&atilde; y&ecirc;n t&acirc;m, v&igrave; hệ thống đ&atilde; hết tạp kh&iacute; v&agrave; ho&agrave;n to&agrave;n k&iacute;n.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoListParagraph\" style=\"margin-bottom:9.0pt;mso-add-space:auto;\r\ntext-indent:-18.0pt;line-height:normal;mso-outline-level:3;mso-list:l1 level1 lfo4;\r\nbackground:white;vertical-align:baseline\"><!--[if !supportLists]--><span style=\"font-size:14.0pt;font-family:Wingdings;mso-fareast-font-family:Wingdings;\r\nmso-bidi-font-family:Wingdings\"><span style=\"mso-list:Ignore\">&Oslash;<span style=\"font:7.0pt &quot;Times New Roman&quot;\"> </span></span></span><!--[endif]--><b style=\"mso-bidi-font-weight:normal\"><u><span style=\"font-size:14.0pt;\r\nfont-family:&quot;Arial&quot;,sans-serif;mso-fareast-font-family:&quot;Times New Roman&quot;\">Bước 3</span></u></b><b style=\"mso-bidi-font-weight:normal\"><span style=\"font-size:\r\n14.0pt;font-family:&quot;Arial&quot;,sans-serif;mso-fareast-font-family:&quot;Times New Roman&quot;\">: Tiến h&agrave;nh nạp gas<o:p></o:p></span></b></p>\r\n\r\n<p class=\"MsoNormal\" style=\"margin-bottom:15.0pt;line-height:normal;background:\r\nwhite;vertical-align:baseline\"><span lang=\"VI\" style=\"font-size:14.0pt;\r\nfont-family:&quot;Arial&quot;,sans-serif;mso-fareast-font-family:&quot;Times New Roman&quot;;\r\nmso-ansi-language:VI\"><span style=\"mso-spacerun:yes\">&nbsp;&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size:14.0pt;font-family:&quot;Arial&quot;,sans-serif;mso-fareast-font-family:\r\n&quot;Times New Roman&quot;\">Mở van kh&oacute;a gas ở b&igrave;nh gas ra hết cỡ rồi mở van kh&oacute;a gas ở đồng hồ ra giới hạn gas ở đồng hồ gas đến khoảng 250 psi v&agrave; cần kh&oacute;a van gas ở đồng hồ đ&oacute;ng lại.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"margin-bottom:15.0pt;line-height:normal;background:\r\nwhite;vertical-align:baseline\"><span lang=\"VI\" style=\"font-size:14.0pt;\r\nfont-family:&quot;Arial&quot;,sans-serif;mso-fareast-font-family:&quot;Times New Roman&quot;;\r\nmso-ansi-language:VI\"><span style=\"mso-spacerun:yes\">&nbsp;&nbsp;&nbsp;&nbsp; </span></span><span style=\"font-size:14.0pt;font-family:&quot;Arial&quot;,sans-serif;mso-fareast-font-family:\r\n&quot;Times New Roman&quot;\">Bạn chỉ mở van gas ở đồng hồ khoảng từ 15 đến 20 gi&acirc;y v&agrave; kh&oacute;a lại ngay cho đến khi n&agrave;o m&aacute;y b&aacute;o d&ograve;ng m&aacute;y lạnh ở đồng hồ bằng với th&ocirc;ng số ghi tr&ecirc;n điều h&ograve;a l&agrave; được.<o:p></o:p></span></p>\r\n', '', 'Lh: 0932 876 323. Bơm ga điều hòa tại nhà. Các loại ga thông dụng đang có mặt trên thị trường hiện nay như: Gas R22, Gas R410A, Gas R32.Uy tín, chất lượng cao.', 'Bơm ga điều hòa tại Bình Dương', 'Thay ga điều hòa tại nhà Bình Dương', '', '', '', 'Bom ga dieu hoa tai nha Binh Duong', '', '', 'bom-ga-dieu-hoa-tai-binh-duong', ' 06/08/2026 ', 1, '', '5092', '5092', '5092bomgamaylanh.jpg', '5092', '5092', 14, 0);
INSERT INTO `tin_dichvu` (`id`, `hinhanh`, `noidung`, `trangchu`, `mota`, `tieude`, `tieude_en`, `noidung_en`, `mota_en`, `title`, `tukhoa`, `tukhoa2`, `facebook`, `linkurl`, `ngay`, `xem`, `nguon`, `hinhqcab`, `hinhqcabc`, `hinhndab`, `hinhndabc`, `hinhndabcd`, `thuocloai`, `noibat`) VALUES
(129, '2050suathietbi-maylanhcongnghiep-binhduong.gif', '<p>&nbsp;<span style=\"text-align: justify; font-size: 13pt; line-height: 115%; font-family: Arial, &quot;sans-serif&quot;;\">Khi m&aacute;y lạnh của bạn xuất hiện những sự cố bất thường. H&atilde;y li&ecirc;n hệ dịch vụ sửa m&aacute;y lạnh Tại B&igrave;nh Dương của <b>C&ocirc;ng Ty Tấn T&agrave;i</b> qua số </span><b style=\"text-align: justify;\"><span style=\"font-size:13.0pt;line-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;\r\nmso-fareast-font-family:&quot;Times New Roman&quot;;color:red\">HOTLINE:</span></b><span style=\"text-align: justify; font-size: 13pt; line-height: 115%; font-family: Arial, &quot;sans-serif&quot;; color: red;\"> </span><span style=\"text-align: justify; font-size: 13pt; line-height: 115%; font-family: Arial, &quot;sans-serif&quot;;\">0932 876 323 để được hỗ trợ.</span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align:justify\"><strong><span style=\"font-size:13.0pt;\r\nline-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;mso-fareast-font-family:&quot;Times New Roman&quot;;\r\ncolor:black\">B&igrave;nh Dương</span></strong><span style=\"font-size:13.0pt;\r\nline-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;mso-fareast-font-family:&quot;Times New Roman&quot;;\r\ncolor:black\"> l&agrave; một th&agrave;nh phố trẻ, c&oacute; tốc độ ph&aacute;t triển đ&ocirc; thị h&oacute;a mạnh mẽ, địa b&agrave;n liền kề với TP. HCM n&ecirc;n trong những năm gần đ&acirc;y, nhu cầu thi c&ocirc;ng lắp đặt, sửa chữa bảo tr&igrave; m&aacute;y lạnh cũng tăng cao một c&aacute;ch đột biến.Trong đ&oacute; c&oacute; rất nhiều kh&aacute;ch h&agrave;ng đ&atilde; t&igrave;m li&ecirc;n hệ đến c&aacute;c dịch vụ của <span style=\"color: rgb(255, 0, 0);\"><strong>C&ocirc;ng ty TNHH Cơ Điện Lạnh Tấn T&agrave;i</strong></span> ch&uacute;ng t&ocirc;i.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-size:13.0pt;\r\nline-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;mso-fareast-font-family:&quot;Times New Roman&quot;;\r\ncolor:black\">Dịch vụ sửa m&aacute;y lạnh tại nh&agrave; khu vực B&igrave;nh Dương, sửa chữa nhanh ch&oacute;ng, chuy&ecirc;n nghiệp, gi&aacute; cạnh tranh. Với hệ thống dịch vụ rộng khắp, ch&uacute;ng t&ocirc;i sẽ đến phục vụ tận nh&agrave; sau 15 -30 ph&uacute;t.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-size:13.0pt;\r\nline-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;mso-fareast-font-family:&quot;Times New Roman&quot;;\r\ncolor:black\">Sửa chữa khắc phục tại nh&agrave; gi&uacute;p tiết kiệm thời gian qu&yacute; b&aacute;u của qu&yacute; kh&aacute;ch.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-size:13.0pt;\r\nline-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;mso-fareast-font-family:&quot;Times New Roman&quot;;\r\ncolor:black\">Với c&aacute;i n&oacute;ng oi bức của m&ugrave;a h&egrave; như thế th&igrave; chiếc m&aacute;y lạnh l&agrave; rất cần thiết cho mọi nh&agrave;. Nhưng một ng&agrave;y kh&ocirc;ng may m&aacute;y lạnh nh&agrave; bạn c&oacute; vấn đề :m&aacute;y lạnh kh&ocirc;ng lạnh ,m&aacute;y lạnh kh&ocirc;ng v&agrave;o điện&hellip;&hellip;<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-size:13.0pt;\r\nline-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;mso-fareast-font-family:&quot;Times New Roman&quot;;\r\ncolor:black\">Đừng lo h&atilde;y để ch&uacute;ng t&ocirc;i dịch vụ chuy&ecirc;n sửa chữa m&aacute;y lạnh sẽ<span style=\"mso-spacerun:yes\">&nbsp; </span>gi&uacute;p cho chiếc m&aacute;y y&ecirc;u qu&yacute; của bạn hoạt động lại b&igrave;nh thường.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\"><b style=\"mso-bidi-font-weight:normal\"><span style=\"font-size:20.0pt;line-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;\r\ncolor:red\">Những dấu hiệu cho thấy bạn cần sửa m&aacute;y lạnh ngay lập tức<o:p></o:p></span></b></p>\r\n\r\n<p class=\"MsoNormal\"><span style=\"font-size:13.0pt;line-height:115%;font-family:\r\n&quot;Arial&quot;,&quot;sans-serif&quot;\">&ndash; M&aacute;y lạnh k&ecirc;u to, hay g&acirc;y ra tiếng ồn lớn.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\"><span style=\"font-size:13.0pt;line-height:115%;font-family:\r\n&quot;Arial&quot;,&quot;sans-serif&quot;\">&ndash; Tiếng ồn ph&aacute;t ra từ d&agrave;n n&oacute;ng.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\"><span style=\"font-size:13.0pt;line-height:115%;font-family:\r\n&quot;Arial&quot;,&quot;sans-serif&quot;\">&ndash; Tiếng ồn ph&aacute;t ra từ d&agrave;n lạnh.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\"><span style=\"font-size:13.0pt;line-height:115%;font-family:\r\n&quot;Arial&quot;,&quot;sans-serif&quot;\">&ndash; Block m&aacute;y lạnh kh&ocirc;ng hoạt động.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\"><span style=\"font-size:13.0pt;line-height:115%;font-family:\r\n&quot;Arial&quot;,&quot;sans-serif&quot;\">&ndash; M&aacute;y lạnh qu&aacute; lạnh so với nhiệt độ điều chỉnh.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\"><span style=\"font-size:13.0pt;line-height:115%;font-family:\r\n&quot;Arial&quot;,&quot;sans-serif&quot;\">&ndash; M&aacute;y lạnh chạy nhưng kh&ocirc;ng m&aacute;t.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\"><span style=\"font-size:13.0pt;line-height:115%;font-family:\r\n&quot;Arial&quot;,&quot;sans-serif&quot;\">&ndash; M&aacute;y lạnh kh&ocirc;ng hoạt động được.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\"><span style=\"font-size:13.0pt;line-height:115%;font-family:\r\n&quot;Arial&quot;,&quot;sans-serif&quot;\">&ndash; Quạt d&agrave;n lạnh m&aacute;y lạnh kh&ocirc;ng chạy.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\"><span style=\"font-size:13.0pt;line-height:115%;font-family:\r\n&quot;Arial&quot;,&quot;sans-serif&quot;\">&ndash; Quạt d&agrave;n n&oacute;ng m&aacute;y lạnh kh&ocirc;ng chạy.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\"><span style=\"font-size:13.0pt;line-height:115%;font-family:\r\n&quot;Arial&quot;,&quot;sans-serif&quot;\">&ndash; M&aacute;y lạnh kh&ocirc;ng chảy nước khi hoạt động.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\"><span style=\"font-size:13.0pt;line-height:115%;font-family:\r\n&quot;Arial&quot;,&quot;sans-serif&quot;\">&ndash; M&aacute;y lạnh khi chạy c&oacute; m&ugrave;i h&ocirc;i kh&oacute; chịu.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\"><span style=\"font-size:13.0pt;line-height:115%;font-family:\r\n&quot;Arial&quot;,&quot;sans-serif&quot;\">&ndash; M&aacute;y lạnh bị x&igrave; ga.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\"><span style=\"font-size:13.0pt;line-height:115%;font-family:\r\n&quot;Arial&quot;,&quot;sans-serif&quot;\">&ndash; M&aacute;y lạnh kh&ocirc;ng nhận t&iacute;n hiệu, b&aacute;o lỗi bo mạch.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\"><span style=\"font-size:13.0pt;line-height:115%;font-family:\r\n&quot;Arial&quot;,&quot;sans-serif&quot;\">Khi m&aacute;y lạnh của bạn xuất hiện những sự cố bất thường. H&atilde;y li&ecirc;n hệ dịch vụ sửa m&aacute;y lạnh B&igrave;nh Dương của C&ocirc;ng Ty Tấn T&agrave;i qua số <b style=\"mso-bidi-font-weight:normal\"><span style=\"color:red\">HOTLINE</span></b>: <b style=\"mso-bidi-font-weight:normal\">0932 876 323</b> để được hỗ trợ.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-size:13.0pt;\r\nline-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;color:#262626;mso-themecolor:\r\ntext1;mso-themetint:217;mso-style-textfill-fill-color:#262626;mso-style-textfill-fill-themecolor:\r\ntext1;mso-style-textfill-fill-alpha:100.0%;mso-style-textfill-fill-colortransforms:\r\n&quot;lumm=85000 lumo=15000&quot;;background:white\">Ngo&agrave;i ra ch&uacute;ng t&ocirc;i c&ograve;n cung cấp dịch vụ vệ sinh m&aacute;y lạnh v&agrave; nạp gas m&aacute;y lạnh.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align:justify\"><b style=\"mso-bidi-font-weight:\r\nnormal\"><span style=\"font-size:13.0pt;line-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;\r\ncolor:#262626;mso-themecolor:text1;mso-themetint:217;mso-style-textfill-fill-color:\r\n#262626;mso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-alpha:\r\n100.0%;mso-style-textfill-fill-colortransforms:&quot;lumm=85000 lumo=15000&quot;;\r\nbackground:white\">L&agrave;m việc tại nh&agrave; tr&ecirc;n tất cả c&aacute;c quận tại B&igrave;nh Dương</span></b></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size: 13pt; line-height: 19.9333px; font-family: Wingdings; color: rgb(38, 38, 38);\">&uuml;<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;</span></span><b><span style=\"font-size: 13pt; line-height: 19.9333px; font-family: Arial, &quot;sans-serif&quot;; color: rgb(38, 38, 38); background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">sửa m&aacute;y lạnh Thủ Dầu Một<o:p></o:p></span></b></li>\r\n	<li><span style=\"font-size: 13pt; line-height: 19.9333px; font-family: Wingdings; color: rgb(38, 38, 38);\">&uuml;<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;</span></span><b><span style=\"font-size: 13pt; line-height: 19.9333px; font-family: Arial, &quot;sans-serif&quot;; color: rgb(38, 38, 38); background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">sửa m&aacute;y lạnh Dĩ An<o:p></o:p></span></b></li>\r\n	<li><span style=\"font-size: 13pt; line-height: 19.9333px; font-family: Wingdings; color: rgb(38, 38, 38);\">&uuml;<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;</span></span><b><span style=\"font-size: 13pt; line-height: 19.9333px; font-family: Arial, &quot;sans-serif&quot;; color: rgb(38, 38, 38); background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">sửa m&aacute;y lạnh T&acirc;n Uy&ecirc;n<o:p></o:p></span></b></li>\r\n	<li><span style=\"font-size: 13pt; line-height: 19.9333px; font-family: Wingdings; color: rgb(38, 38, 38);\">&uuml;<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;</span></span><b><span style=\"font-size: 13pt; line-height: 19.9333px; font-family: Arial, &quot;sans-serif&quot;; color: rgb(38, 38, 38); background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">sửa m&aacute;y lạnh Bến C&aacute;t<o:p></o:p></span></b></li>\r\n	<li><span style=\"font-size: 13pt; line-height: 19.9333px; font-family: Wingdings; color: rgb(38, 38, 38);\">&uuml;<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;</span></span><b><span style=\"font-size: 13pt; line-height: 19.9333px; font-family: Arial, &quot;sans-serif&quot;; color: rgb(38, 38, 38); background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">sửa m&aacute;y lạnh Thuận An<o:p></o:p></span></b></li>\r\n	<li><span style=\"font-size: 13pt; line-height: 19.9333px; font-family: Wingdings; color: rgb(38, 38, 38);\">&uuml;<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;</span></span><b><span style=\"font-size: 13pt; line-height: 19.9333px; font-family: Arial, &quot;sans-serif&quot;; color: rgb(38, 38, 38); background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">sửa m&aacute;y lạnh Bầu Tiếng<o:p></o:p></span></b></li>\r\n	<li><span style=\"font-size: 13pt; line-height: 19.9333px; font-family: Wingdings; color: rgb(38, 38, 38);\">&uuml;<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;</span></span><b><span style=\"font-size: 13pt; line-height: 19.9333px; font-family: Arial, &quot;sans-serif&quot;; color: rgb(38, 38, 38); background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">sửa chữa m&aacute;y lạnh Ph&uacute; Gi&aacute;o<o:p></o:p></span></b></li>\r\n	<li><span style=\"font-size: 13pt; line-height: 19.9333px; font-family: Wingdings; color: rgb(38, 38, 38);\">&uuml;<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;</span></span><b><span style=\"font-size: 13pt; line-height: 19.9333px; font-family: Arial, &quot;sans-serif&quot;; color: rgb(38, 38, 38); background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">sửa m&aacute;y lạnh quận Bầu B&agrave;ng<o:p></o:p></span></b><b><span style=\"font-size: 13pt; line-height: 115%; font-family: Arial, &quot;sans-serif&quot;; color: rgb(38, 38, 38); background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\"><o:p></o:p></span></b></li>\r\n	<li><span style=\"font-size: 13pt; line-height: 19.9333px; font-family: Wingdings; color: rgb(38, 38, 38);\">&uuml;<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;</span></span><b><span style=\"font-size: 13pt; line-height: 19.9333px; font-family: Arial, &quot;sans-serif&quot;; color: rgb(38, 38, 38); background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">sửa m&aacute;y lạnh quận Thủ Đức Hồ Ch&iacute; Minh</span></b></li>\r\n</ul>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-size:13.0pt;\r\nline-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;color:#262626;mso-themecolor:\r\ntext1;mso-themetint:217;mso-style-textfill-fill-color:#262626;mso-style-textfill-fill-themecolor:\r\ntext1;mso-style-textfill-fill-alpha:100.0%;mso-style-textfill-fill-colortransforms:\r\n&quot;lumm=85000 lumo=15000&quot;;background:white\">V&agrave; nhiều Quận huyện kh&aacute;c nhau tại S&agrave;i G&ograve;n: Sửa m&aacute;y lạnh Quận Thủ Đức, sửa m&aacute;y lạnh G&ograve; Vấp...vv<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align:justify\"><b style=\"mso-bidi-font-weight:\r\nnormal\"><span style=\"font-size:13.0pt;line-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;\r\ncolor:#262626;mso-themecolor:text1;mso-themetint:217;mso-style-textfill-fill-color:\r\n#262626;mso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-alpha:\r\n100.0%;mso-style-textfill-fill-colortransforms:&quot;lumm=85000 lumo=15000&quot;;\r\nbackground:white\">NHỮNG NGUY&Ecirc;N NH&Acirc;N KHIẾN M&Aacute;Y LẠNH HƯ HỎNG<o:p></o:p></span></b></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align:justify\"><b style=\"mso-bidi-font-weight:\r\nnormal\"><span style=\"font-size:13.0pt;line-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;\r\ncolor:#262626;mso-themecolor:text1;mso-themetint:217;mso-style-textfill-fill-color:\r\n#262626;mso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-alpha:\r\n100.0%;mso-style-textfill-fill-colortransforms:&quot;lumm=85000 lumo=15000&quot;;\r\nbackground:white\">M&aacute;y k&eacute;m lạnh<o:p></o:p></span></b></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-size:13.0pt;\r\nline-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;color:#262626;mso-themecolor:\r\ntext1;mso-themetint:217;mso-style-textfill-fill-color:#262626;mso-style-textfill-fill-themecolor:\r\ntext1;mso-style-textfill-fill-alpha:100.0%;mso-style-textfill-fill-colortransforms:\r\n&quot;lumm=85000 lumo=15000&quot;;background:white\">M&aacute;y kh&ocirc;ng đủ c&ocirc;ng suất do lắp v&agrave;o ph&ograve;ng qu&aacute; lớn (m&aacute;y 1HP chỉ c&oacute; thể l&agrave;m lạnh cho ph&ograve;ng sinh hoạt gia đ&igrave;nh tối đa 45m3 ở nhiệt độ khoảng 24-25 độ C)<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align:justify\"><b style=\"mso-bidi-font-weight:\r\nnormal\"><span style=\"font-size:13.0pt;line-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;\r\ncolor:#262626;mso-themecolor:text1;mso-themetint:217;mso-style-textfill-fill-color:\r\n#262626;mso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-alpha:\r\n100.0%;mso-style-textfill-fill-colortransforms:&quot;lumm=85000 lumo=15000&quot;;\r\nbackground:white\">D&agrave;n lạnh v&agrave; d&agrave;n n&oacute;ng bị dơ:</span></b><span style=\"font-size:\r\n13.0pt;line-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;color:#262626;\r\nmso-themecolor:text1;mso-themetint:217;mso-style-textfill-fill-color:#262626;\r\nmso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-alpha:100.0%;\r\nmso-style-textfill-fill-colortransforms:&quot;lumm=85000 lumo=15000&quot;;background:\r\nwhite\"> Cần phải vệ sinh m&aacute;y lạnh.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align:justify\"><b style=\"mso-bidi-font-weight:\r\nnormal\"><span style=\"font-size:13.0pt;line-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;\r\ncolor:#262626;mso-themecolor:text1;mso-themetint:217;mso-style-textfill-fill-color:\r\n#262626;mso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-alpha:\r\n100.0%;mso-style-textfill-fill-colortransforms:&quot;lumm=85000 lumo=15000&quot;;\r\nbackground:white\">Bị thiếu gas:</span></b><span style=\"font-size:13.0pt;\r\nline-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;color:#262626;mso-themecolor:\r\ntext1;mso-themetint:217;mso-style-textfill-fill-color:#262626;mso-style-textfill-fill-themecolor:\r\ntext1;mso-style-textfill-fill-alpha:100.0%;mso-style-textfill-fill-colortransforms:\r\n&quot;lumm=85000 lumo=15000&quot;;background:white\"> Quan s&aacute;t 2 ống đồng nối v&agrave;o d&agrave;n n&oacute;ng, ống nhỏ bị b&aacute;m tuyết, ống lớn kh&ocirc;ng ướt nếu sờ v&agrave;o kh&ocirc;ng lạnh lắm. Gi&oacute; thổi ra d&agrave;n n&oacute;ng kh&ocirc;ng n&oacute;ng lắm.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align:justify\"><b style=\"mso-bidi-font-weight:\r\nnormal\"><span style=\"font-size:13.0pt;line-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;\r\ncolor:#262626;mso-themecolor:text1;mso-themetint:217;mso-style-textfill-fill-color:\r\n#262626;mso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-alpha:\r\n100.0%;mso-style-textfill-fill-colortransforms:&quot;lumm=85000 lumo=15000&quot;;\r\nbackground:white\">M&aacute;y kh&ocirc;ng lạnh hoặc l&uacute;c lạnh l&uacute;c kh&ocirc;ng<o:p></o:p></span></b></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-size:13.0pt;\r\nline-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;color:#262626;mso-themecolor:\r\ntext1;mso-themetint:217;mso-style-textfill-fill-color:#262626;mso-style-textfill-fill-themecolor:\r\ntext1;mso-style-textfill-fill-alpha:100.0%;mso-style-textfill-fill-colortransforms:\r\n&quot;lumm=85000 lumo=15000&quot;;background:white\">Trường hợp m&aacute;y l&uacute;c lạnh l&uacute;c kh&ocirc;ng l&agrave; do chỉnh remote ở chế độ Dry hoặc sự cố ở d&agrave;n n&oacute;ng hoặc bị thiếu gas.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-size:13.0pt;\r\nline-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;color:#262626;mso-themecolor:\r\ntext1;mso-themetint:217;mso-style-textfill-fill-color:#262626;mso-style-textfill-fill-themecolor:\r\ntext1;mso-style-textfill-fill-alpha:100.0%;mso-style-textfill-fill-colortransforms:\r\n&quot;lumm=85000 lumo=15000&quot;;background:white\">Board điều khiển tr&ecirc;n d&agrave;n lạnh hư.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align:justify\"><b style=\"mso-bidi-font-weight:\r\nnormal\"><span style=\"font-size:13.0pt;line-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;\r\ncolor:#262626;mso-themecolor:text1;mso-themetint:217;mso-style-textfill-fill-color:\r\n#262626;mso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-alpha:\r\n100.0%;mso-style-textfill-fill-colortransforms:&quot;lumm=85000 lumo=15000&quot;;\r\nbackground:white\">X&igrave; hết gas:</span></b><span style=\"font-size:13.0pt;\r\nline-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;color:#262626;mso-themecolor:\r\ntext1;mso-themetint:217;mso-style-textfill-fill-color:#262626;mso-style-textfill-fill-themecolor:\r\ntext1;mso-style-textfill-fill-alpha:100.0%;mso-style-textfill-fill-colortransforms:\r\n&quot;lumm=85000 lumo=15000&quot;;background:white\"> Kiểm tra rất dễ bằng c&aacute;ch quan s&aacute;t 2 ống đồng nối v&agrave;o d&agrave;n n&oacute;ng, cả 2 ống nhỏ v&agrave; lớn đều kh&ocirc;ng ướt, sờ v&agrave;o kh&ocirc;ng lạnh (khi m&aacute;y lạnh hoạt động tốt, cả 2 ống đều c&oacute; nhiệt độ gần bằng nhau khoảng 57oC, nh&igrave;n bằng mắt 2 ống đều bị ướt). Gi&oacute; thổi ra d&agrave;n n&oacute;ng kh&ocirc;ng n&oacute;ng.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align:justify\"><b style=\"mso-bidi-font-weight:\r\nnormal\"><span style=\"font-size:13.0pt;line-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;\r\ncolor:#262626;mso-themecolor:text1;mso-themetint:217;mso-style-textfill-fill-color:\r\n#262626;mso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-alpha:\r\n100.0%;mso-style-textfill-fill-colortransforms:&quot;lumm=85000 lumo=15000&quot;;\r\nbackground:white\">Chỉnh chế độ hoạt động tr&ecirc;n remote kh&ocirc;ng đ&uacute;ng:</span></b><span style=\"font-size:13.0pt;line-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;\r\ncolor:#262626;mso-themecolor:text1;mso-themetint:217;mso-style-textfill-fill-color:\r\n#262626;mso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-alpha:\r\n100.0%;mso-style-textfill-fill-colortransforms:&quot;lumm=85000 lumo=15000&quot;;\r\nbackground:white\"> Kiểm tra tr&ecirc;n remote đ&atilde; chỉnh đ&uacute;ng chế độ (mode) Cool hoặc Auto kh&ocirc;ng, nếu kh&ocirc;ng th&igrave; chỉnh lại. C&aacute;c chế độ Dry, Fan, Heat đều kh&ocirc;ng l&agrave;m lạnh. Một số trường hợp bật chế độ Timer cũng c&oacute; thể kh&ocirc;ng lạnh.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align:justify\"><b style=\"mso-bidi-font-weight:\r\nnormal\"><span style=\"font-size:13.0pt;line-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;\r\ncolor:#262626;mso-themecolor:text1;mso-themetint:217;mso-style-textfill-fill-color:\r\n#262626;mso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-alpha:\r\n100.0%;mso-style-textfill-fill-colortransforms:&quot;lumm=85000 lumo=15000&quot;;\r\nbackground:white\">M&aacute;y n&eacute;n (block) bị sự cố:</span></b><span style=\"font-size:\r\n13.0pt;line-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;color:#262626;\r\nmso-themecolor:text1;mso-themetint:217;mso-style-textfill-fill-color:#262626;\r\nmso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-alpha:100.0%;\r\nmso-style-textfill-fill-colortransforms:&quot;lumm=85000 lumo=15000&quot;;background:\r\nwhite\"> Quạt d&agrave;n n&oacute;ng quay nhưng m&aacute;y n&eacute;n kh&ocirc;ng chạy(kh&ocirc;ng nghe tiếng m&aacute;y n&eacute;n chạy)<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align:justify\"><b style=\"mso-bidi-font-weight:\r\nnormal\"><span style=\"font-size:13.0pt;line-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;\r\ncolor:#262626;mso-themecolor:text1;mso-themetint:217;mso-style-textfill-fill-color:\r\n#262626;mso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-alpha:\r\n100.0%;mso-style-textfill-fill-colortransforms:&quot;lumm=85000 lumo=15000&quot;;\r\nbackground:white\">Quạt d&agrave;n n&oacute;ng bị sự cố:</span></b><span style=\"font-size:\r\n13.0pt;line-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;color:#262626;\r\nmso-themecolor:text1;mso-themetint:217;mso-style-textfill-fill-color:#262626;\r\nmso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-alpha:100.0%;\r\nmso-style-textfill-fill-colortransforms:&quot;lumm=85000 lumo=15000&quot;;background:\r\nwhite\"> Theo d&otilde;i khoảnh 10-20 ph&uacute;t kh&ocirc;ng thấy quạt d&agrave;n n&oacute;ng quay hoặc quay chậm hơn b&igrave;nh thường. Khi quạt d&agrave;n n&oacute;ng kh&ocirc;ng quay hoặc quay chậm, m&aacute;y n&eacute;n (block) sẽ chạy v&agrave; ngưng bất thường (lắng nghe tiếng m&aacute;y n&eacute;n chạy)<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align:justify\"><b style=\"mso-bidi-font-weight:\r\nnormal\"><span style=\"font-size:13.0pt;line-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;\r\ncolor:#262626;mso-themecolor:text1;mso-themetint:217;mso-style-textfill-fill-color:\r\n#262626;mso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-alpha:\r\n100.0%;mso-style-textfill-fill-colortransforms:&quot;lumm=85000 lumo=15000&quot;;\r\nbackground:white\">Quạt d&agrave;n lạnh kh&ocirc;ng chạy.<o:p></o:p></span></b></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-size:13.0pt;\r\nline-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;color:#262626;mso-themecolor:\r\ntext1;mso-themetint:217;mso-style-textfill-fill-color:#262626;mso-style-textfill-fill-themecolor:\r\ntext1;mso-style-textfill-fill-alpha:100.0%;mso-style-textfill-fill-colortransforms:\r\n&quot;lumm=85000 lumo=15000&quot;;background:white\">Động cơ quạt bị ngắn mạch hay chạm vỏ.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-size:13.0pt;\r\nline-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;color:#262626;mso-themecolor:\r\ntext1;mso-themetint:217;mso-style-textfill-fill-color:#262626;mso-style-textfill-fill-themecolor:\r\ntext1;mso-style-textfill-fill-alpha:100.0%;mso-style-textfill-fill-colortransforms:\r\n&quot;lumm=85000 lumo=15000&quot;;background:white\">Cuộn d&acirc;y contactor quạt bị hư.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-size:13.0pt;\r\nline-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;color:#262626;mso-themecolor:\r\ntext1;mso-themetint:217;mso-style-textfill-fill-color:#262626;mso-style-textfill-fill-themecolor:\r\ntext1;mso-style-textfill-fill-alpha:100.0%;mso-style-textfill-fill-colortransforms:\r\n&quot;lumm=85000 lumo=15000&quot;;background:white\">Tụ điện bị hư hay ngắn mạch.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-size:13.0pt;\r\nline-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;color:#262626;mso-themecolor:\r\ntext1;mso-themetint:217;mso-style-textfill-fill-color:#262626;mso-style-textfill-fill-themecolor:\r\ntext1;mso-style-textfill-fill-alpha:100.0%;mso-style-textfill-fill-colortransforms:\r\n&quot;lumm=85000 lumo=15000&quot;;background:white\">Ngắn mạch hay đứt d&acirc;y.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align:justify\"><b style=\"mso-bidi-font-weight:\r\nnormal\"><span style=\"font-size:13.0pt;line-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;\r\ncolor:#262626;mso-themecolor:text1;mso-themetint:217;mso-style-textfill-fill-color:\r\n#262626;mso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-alpha:\r\n100.0%;mso-style-textfill-fill-colortransforms:&quot;lumm=85000 lumo=15000&quot;;\r\nbackground:white\">Block kh&ocirc;ng chạy<o:p></o:p></span></b></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-size:13.0pt;\r\nline-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;color:#262626;mso-themecolor:\r\ntext1;mso-themetint:217;mso-style-textfill-fill-color:#262626;mso-style-textfill-fill-themecolor:\r\ntext1;mso-style-textfill-fill-alpha:100.0%;mso-style-textfill-fill-colortransforms:\r\n&quot;lumm=85000 lumo=15000&quot;;background:white\">Block được xem l&agrave; tr&aacute;i tim của m&aacute;y lạnh, khi block kh&ocirc;ng chạy th&igrave; m&aacute;y lạnh sẽ kh&ocirc;ng lạnh. Một số nguy&ecirc;n nh&acirc;n khiến cho block kh&ocirc;ng chạy.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-size:13.0pt;\r\nline-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;color:#262626;mso-themecolor:\r\ntext1;mso-themetint:217;mso-style-textfill-fill-color:#262626;mso-style-textfill-fill-themecolor:\r\ntext1;mso-style-textfill-fill-alpha:100.0%;mso-style-textfill-fill-colortransforms:\r\n&quot;lumm=85000 lumo=15000&quot;;background:white\">Ch&aacute;y một trong c&aacute;c cuộn d&acirc;y động cơ b&ecirc;n trong, trường hợp n&agrave;y c&oacute; thể dẫn tới nhảy CB nguồn.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align:justify\"><b style=\"mso-bidi-font-weight:\r\nnormal\"><span style=\"font-size:13.0pt;line-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;\r\ncolor:#262626;mso-themecolor:text1;mso-themetint:217;mso-style-textfill-fill-color:\r\n#262626;mso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-alpha:\r\n100.0%;mso-style-textfill-fill-colortransforms:&quot;lumm=85000 lumo=15000&quot;;\r\nbackground:white\">Nhảy thermic bảo vệ m&aacute;y n&eacute;n:</span></b><span style=\"font-size:13.0pt;line-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;\r\ncolor:#262626;mso-themecolor:text1;mso-themetint:217;mso-style-textfill-fill-color:\r\n#262626;mso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-alpha:\r\n100.0%;mso-style-textfill-fill-colortransforms:&quot;lumm=85000 lumo=15000&quot;;\r\nbackground:white\"> thường do hư tụ, quạt d&agrave;n n&oacute;ng yếu hoặc hư, motor m&aacute;y n&eacute;n kh&ocirc;ng quay.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-size:13.0pt;\r\nline-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;color:#262626;mso-themecolor:\r\ntext1;mso-themetint:217;mso-style-textfill-fill-color:#262626;mso-style-textfill-fill-themecolor:\r\ntext1;mso-style-textfill-fill-alpha:100.0%;mso-style-textfill-fill-colortransforms:\r\n&quot;lumm=85000 lumo=15000&quot;;background:white\">Mất nguồn cấp đến m&aacute;y n&eacute;n: do lỗ do board điều khiển, contactor kh&ocirc;ng đ&oacute;ng, hở mạch.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align:justify\"><b style=\"mso-bidi-font-weight:\r\nnormal\"><span style=\"font-size:13.0pt;line-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;\r\ncolor:#262626;mso-themecolor:text1;mso-themetint:217;mso-style-textfill-fill-color:\r\n#262626;mso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-alpha:\r\n100.0%;mso-style-textfill-fill-colortransforms:&quot;lumm=85000 lumo=15000&quot;;\r\nbackground:white\">M&aacute;y lạnh bị chảy nước<o:p></o:p></span></b></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-size:13.0pt;\r\nline-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;color:#262626;mso-themecolor:\r\ntext1;mso-themetint:217;mso-style-textfill-fill-color:#262626;mso-style-textfill-fill-themecolor:\r\ntext1;mso-style-textfill-fill-alpha:100.0%;mso-style-textfill-fill-colortransforms:\r\n&quot;lumm=85000 lumo=15000&quot;;background:white\">Do d&agrave;n lạnh b&aacute;m nhiều bụi bẩn<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-size:13.0pt;\r\nline-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;color:#262626;mso-themecolor:\r\ntext1;mso-themetint:217;mso-style-textfill-fill-color:#262626;mso-style-textfill-fill-themecolor:\r\ntext1;mso-style-textfill-fill-alpha:100.0%;mso-style-textfill-fill-colortransforms:\r\n&quot;lumm=85000 lumo=15000&quot;;background:white\">Đường ống tho&aacute;t nước bị nghẹt<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-size:13.0pt;\r\nline-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;color:#262626;mso-themecolor:\r\ntext1;mso-themetint:217;mso-style-textfill-fill-color:#262626;mso-style-textfill-fill-themecolor:\r\ntext1;mso-style-textfill-fill-alpha:100.0%;mso-style-textfill-fill-colortransforms:\r\n&quot;lumm=85000 lumo=15000&quot;;background:white\">Qu&aacute; tr&igrave;nh vệ sinh bị đọng nước b&ecirc;n trong d&agrave;n lạnh<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-size:13.0pt;\r\nline-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;color:#262626;mso-themecolor:\r\ntext1;mso-themetint:217;mso-style-textfill-fill-color:#262626;mso-style-textfill-fill-themecolor:\r\ntext1;mso-style-textfill-fill-alpha:100.0%;mso-style-textfill-fill-colortransforms:\r\n&quot;lumm=85000 lumo=15000&quot;;background:white\">L&acirc;u ng&agrave;y kh&ocirc;ng vệ sinh định kỳ m&aacute;y lạnh<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align:justify\"><b style=\"mso-bidi-font-weight:\r\nnormal\"><span style=\"font-size:13.0pt;line-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;\r\ncolor:#262626;mso-themecolor:text1;mso-themetint:217;mso-style-textfill-fill-color:\r\n#262626;mso-style-textfill-fill-themecolor:text1;mso-style-textfill-fill-alpha:\r\n100.0%;mso-style-textfill-fill-colortransforms:&quot;lumm=85000 lumo=15000&quot;;\r\nbackground:white\">M&aacute;y lạnh qu&aacute; lạnh<o:p></o:p></span></b></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-size:13.0pt;\r\nline-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;color:#262626;mso-themecolor:\r\ntext1;mso-themetint:217;mso-style-textfill-fill-color:#262626;mso-style-textfill-fill-themecolor:\r\ntext1;mso-style-textfill-fill-alpha:100.0%;mso-style-textfill-fill-colortransforms:\r\n&quot;lumm=85000 lumo=15000&quot;;background:white\">Bộ điều khiển nhiệt độ (thermostat) bị hư.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-size:13.0pt;\r\nline-height:115%;font-family:&quot;Arial&quot;,&quot;sans-serif&quot;;color:#262626;mso-themecolor:\r\ntext1;mso-themetint:217;mso-style-textfill-fill-color:#262626;mso-style-textfill-fill-themecolor:\r\ntext1;mso-style-textfill-fill-alpha:100.0%;mso-style-textfill-fill-colortransforms:\r\n&quot;lumm=85000 lumo=15000&quot;;background:white\">Chỉnh nhiệt độ xuống qu&aacute; thấp so với nhu cầu sử dụng.<o:p></o:p></span></p>\r\n', '', 'Lh:0932  876 323 Nhanh chóng và chuyên nghiệp trong quá trình tháo lắp là mục tiêu chúng tôi luôn hướng tới. Đội ngũ kỹ thuật tay nghề cao, tháo lắp điều hòa chuyên nghiệp, uy tín chất lượng tại Bình Dương   ', 'Sửa thiết bị máy lạnh Bình Dương', 'Sửa thiết bị điện lạnh Bình Dương', '', '', '', 'Sửa thiết bị điều hòa Bình Dương', '', '', 'sua-thiet-bi-may-lanh-binh-duong', ' 06/08/2026 ', 8, '', '', '', 'sua-thietbi-may-lanh-binh-duong-501.jpg', '', '', 14, 0);
INSERT INTO `tin_dichvu` (`id`, `hinhanh`, `noidung`, `trangchu`, `mota`, `tieude`, `tieude_en`, `noidung_en`, `mota_en`, `title`, `tukhoa`, `tukhoa2`, `facebook`, `linkurl`, `ngay`, `xem`, `nguon`, `hinhqcab`, `hinhqcabc`, `hinhndab`, `hinhndabc`, `hinhndabcd`, `thuocloai`, `noibat`) VALUES
(130, '246suathietbi-maylanhdian-binhduong.gif', '<p>&nbsp;&nbsp;<span style=\"text-align: justify; font-size: 13pt; line-height: 19.9333px; font-family: Arial, &quot;sans-serif&quot;;\">Khi m&aacute;y lạnh của bạn xuất hiện những sự cố bất thường. H&atilde;y li&ecirc;n hệ dịch vụ sửa m&aacute;y lạnh Tại B&igrave;nh Dương của&nbsp;<b>C&ocirc;ng Ty Tấn T&agrave;i</b>&nbsp;qua số&nbsp;</span><b style=\"text-align: justify;\"><span style=\"font-size: 13pt; line-height: 19.9333px; font-family: Arial, &quot;sans-serif&quot;; color: red;\">HOTLINE:</span></b><span style=\"text-align: justify; font-size: 13pt; line-height: 19.9333px; font-family: Arial, &quot;sans-serif&quot;; color: red;\">&nbsp;</span><span style=\"text-align: justify; font-size: 13pt; line-height: 19.9333px; font-family: Arial, &quot;sans-serif&quot;;\">0932 876 323 để được hỗ trợ.</span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong><span style=\"font-size: 13pt; line-height: 19.9333px; font-family: Arial, &quot;sans-serif&quot;;\">Dĩ An B&igrave;nh Dương</span></strong><span style=\"font-size: 13pt; line-height: 19.9333px; font-family: Arial, &quot;sans-serif&quot;;\">&nbsp;l&agrave; một th&agrave;nh phố trẻ, c&oacute; tốc độ ph&aacute;t triển đ&ocirc; thị h&oacute;a mạnh mẽ, địa b&agrave;n liền kề với TP. HCM n&ecirc;n trong những năm gần đ&acirc;y, nhu cầu thi c&ocirc;ng lắp đặt, sửa chữa bảo tr&igrave; m&aacute;y lạnh cũng tăng cao một c&aacute;ch đột biến.Trong đ&oacute; c&oacute; rất nhiều kh&aacute;ch h&agrave;ng đ&atilde; t&igrave;m li&ecirc;n hệ đến c&aacute;c dịch vụ của&nbsp;<span style=\"color: rgb(255, 0, 0);\"><strong>C&ocirc;ng ty TNHH Cơ Điện Lạnh Tấn T&agrave;i</strong></span>&nbsp;ch&uacute;ng t&ocirc;i.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"font-size: 13pt; line-height: 19.9333px; font-family: Arial, &quot;sans-serif&quot;;\">Dịch vụ sửa m&aacute;y lạnh tại nh&agrave; khu vực B&igrave;nh Dương, sửa chữa nhanh ch&oacute;ng, chuy&ecirc;n nghiệp, gi&aacute; cạnh tranh. Với hệ thống dịch vụ rộng khắp, ch&uacute;ng t&ocirc;i sẽ đến phục vụ tận nh&agrave; sau 15 -30 ph&uacute;t.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"font-size: 13pt; line-height: 19.9333px; font-family: Arial, &quot;sans-serif&quot;;\">Sửa chữa khắc phục tại nh&agrave; gi&uacute;p tiết kiệm thời gian qu&yacute; b&aacute;u của qu&yacute; kh&aacute;ch.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"font-size: 13pt; line-height: 19.9333px; font-family: Arial, &quot;sans-serif&quot;;\">Với c&aacute;i n&oacute;ng oi bức của m&ugrave;a h&egrave; như thế th&igrave; chiếc m&aacute;y lạnh l&agrave; rất cần thiết cho mọi nh&agrave;. Nhưng một ng&agrave;y kh&ocirc;ng may m&aacute;y lạnh nh&agrave; bạn c&oacute; vấn đề :m&aacute;y lạnh kh&ocirc;ng lạnh ,m&aacute;y lạnh kh&ocirc;ng v&agrave;o điện&hellip;&hellip;<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"font-size: 13pt; line-height: 19.9333px; font-family: Arial, &quot;sans-serif&quot;;\">Đừng lo h&atilde;y để ch&uacute;ng t&ocirc;i dịch vụ chuy&ecirc;n sửa chữa m&aacute;y lạnh sẽ&nbsp;&nbsp;gi&uacute;p cho chiếc m&aacute;y y&ecirc;u qu&yacute; của bạn hoạt động lại b&igrave;nh thường.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\"><b><span style=\"font-size: 20pt; line-height: 30.6667px; font-family: Arial, &quot;sans-serif&quot;; color: red;\">Những dấu hiệu cho thấy bạn cần sửa m&aacute;y lạnh ngay lập tức<o:p></o:p></span></b></p>\r\n\r\n<p class=\"MsoNormal\"><span style=\"font-size: 13pt; line-height: 19.9333px; font-family: Arial, &quot;sans-serif&quot;;\">&ndash; M&aacute;y lạnh k&ecirc;u to, hay g&acirc;y ra tiếng ồn lớn.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\"><span style=\"font-size: 13pt; line-height: 19.9333px; font-family: Arial, &quot;sans-serif&quot;;\">&ndash; Tiếng ồn ph&aacute;t ra từ d&agrave;n n&oacute;ng.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\"><span style=\"font-size: 13pt; line-height: 19.9333px; font-family: Arial, &quot;sans-serif&quot;;\">&ndash; Tiếng ồn ph&aacute;t ra từ d&agrave;n lạnh.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\"><span style=\"font-size: 13pt; line-height: 19.9333px; font-family: Arial, &quot;sans-serif&quot;;\">&ndash; Block m&aacute;y lạnh kh&ocirc;ng hoạt động.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\"><span style=\"font-size: 13pt; line-height: 19.9333px; font-family: Arial, &quot;sans-serif&quot;;\">&ndash; M&aacute;y lạnh qu&aacute; lạnh so với nhiệt độ điều chỉnh.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\"><span style=\"font-size: 13pt; line-height: 19.9333px; font-family: Arial, &quot;sans-serif&quot;;\">&ndash; M&aacute;y lạnh chạy nhưng kh&ocirc;ng m&aacute;t.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\"><span style=\"font-size: 13pt; line-height: 19.9333px; font-family: Arial, &quot;sans-serif&quot;;\">&ndash; M&aacute;y lạnh kh&ocirc;ng hoạt động được.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\"><span style=\"font-size: 13pt; line-height: 19.9333px; font-family: Arial, &quot;sans-serif&quot;;\">&ndash; Quạt d&agrave;n lạnh m&aacute;y lạnh kh&ocirc;ng chạy.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\"><span style=\"font-size: 13pt; line-height: 19.9333px; font-family: Arial, &quot;sans-serif&quot;;\">&ndash; Quạt d&agrave;n n&oacute;ng m&aacute;y lạnh kh&ocirc;ng chạy.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\"><span style=\"font-size: 13pt; line-height: 19.9333px; font-family: Arial, &quot;sans-serif&quot;;\">&ndash; M&aacute;y lạnh kh&ocirc;ng chảy nước khi hoạt động.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\"><span style=\"font-size: 13pt; line-height: 19.9333px; font-family: Arial, &quot;sans-serif&quot;;\">&ndash; M&aacute;y lạnh khi chạy c&oacute; m&ugrave;i h&ocirc;i kh&oacute; chịu.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\"><span style=\"font-size: 13pt; line-height: 19.9333px; font-family: Arial, &quot;sans-serif&quot;;\">&ndash; M&aacute;y lạnh bị x&igrave; ga.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\"><span style=\"font-size: 13pt; line-height: 19.9333px; font-family: Arial, &quot;sans-serif&quot;;\">&ndash; M&aacute;y lạnh kh&ocirc;ng nhận t&iacute;n hiệu, b&aacute;o lỗi bo mạch.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\"><span style=\"font-size: 13pt; line-height: 19.9333px; font-family: Arial, &quot;sans-serif&quot;;\">Khi m&aacute;y lạnh của bạn xuất hiện những sự cố bất thường. H&atilde;y li&ecirc;n hệ dịch vụ sửa m&aacute;y lạnh B&igrave;nh Dương của C&ocirc;ng Ty Tấn T&agrave;i qua số&nbsp;<b><span style=\"color: red;\">HOTLINE</span></b>:&nbsp;<b>0932 876 323</b>&nbsp;để được hỗ trợ.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><span style=\"font-size: 13pt; line-height: 19.9333px; font-family: Arial, &quot;sans-serif&quot;; color: rgb(38, 38, 38); background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">Ngo&agrave;i ra ch&uacute;ng t&ocirc;i c&ograve;n cung cấp dịch vụ vệ sinh m&aacute;y lạnh v&agrave; nạp gas m&aacute;y lạnh.<o:p></o:p></span></p>\r\n\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><b><span style=\"font-size: 13pt; line-height: 19.9333px; font-family: Arial, &quot;sans-serif&quot;; color: rgb(38, 38, 38); background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">L&agrave;m việc tại nh&agrave; tr&ecirc;n tất cả c&aacute;c quận tại B&igrave;nh Dương</span></b></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size: 13pt; line-height: 19.9333px; font-family: Wingdings; color: rgb(38, 38, 38);